import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import {
    ShoppingCart, DollarSign, Package, Users, Truck,
    Clock, TrendingUp, CheckCircle, AlertTriangle,
    ArrowRightIcon
} from '@heroicons/react/24/outline';
import { useNavigate } from 'react-router-dom';
import adminService from '../../services/adminService';
import StatCard from '../../components/ui/StatCard';
import SectionCard from '../../components/ui/SectionCard';
import StatusBadge from '../../components/ui/StatusBadge';

const AdminOverview = () => {
    const navigate = useNavigate();
    const { data, isLoading } = useQuery({
        queryKey: ['admin-dashboard'],
        queryFn: adminService.getDashboardStats,
    });

    const stats = data?.stats || {};
    const recentOrders = data?.recentOrders || [];
    const ordersByStatus = data?.ordersByStatus || [];

    const statCards = [
        { label: 'Total Orders', value: stats.totalOrders || 0, icon: ShoppingCart, color: 'navy', trend: 12 },
        { label: 'Total Revenue', value: `$${(stats.totalRevenue || 0).toLocaleString()}`, icon: DollarSign, color: 'emerald', trend: 8 },
        { label: 'Products', value: stats.totalProducts || 0, icon: Package, color: 'teal', subtitle: stats.lowStockProducts > 0 ? `${stats.lowStockProducts} low stock` : 'All stocked' },
        { label: 'Sales Reps', value: stats.totalSalesReps || 0, icon: Users, color: 'gold' },
        { label: 'Dispatch', value: stats.totalDispatchPartners || 0, icon: Truck, color: 'purple' },
        { label: 'Pending', value: stats.pendingOrders || 0, icon: Clock, color: 'rose' },
        { label: "Today's Orders", value: stats.todayOrders || 0, icon: TrendingUp, color: 'blue' },
        { label: 'Conversion', value: `${stats.conversionRate || 0}%`, icon: CheckCircle, color: 'navy' },
    ];

    return (
        <div className="space-y-6">
            {/* Welcome Banner */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="relative overflow-hidden bg-gradient-to-r from-brand-800 via-brand-900 to-brand-950 rounded-3xl p-6 lg:p-8 text-white"
            >
                <div className="absolute top-0 right-0 w-64 h-64 bg-gold-500/10 rounded-full -translate-y-1/2 translate-x-1/2 blur-3xl" />
                <div className="absolute bottom-0 left-0 w-48 h-48 bg-brand-500/20 rounded-full translate-y-1/2 -translate-x-1/2 blur-3xl" />
                <div className="relative">
                    <h2 className="text-2xl lg:text-3xl font-bold">Welcome back! 👋</h2>
                    <p className="text-brand-200 mt-2 max-w-lg">Here's what's happening with your business today. You have {stats.pendingOrders || 0} pending orders that need attention.</p>
                    <div className="flex gap-3 mt-4">
                        <button onClick={() => navigate('/admin/dashboard/orders')} className="px-5 py-2.5 bg-white/20 text-white rounded-xl hover:bg-white/30 transition font-semibold text-sm backdrop-blur-sm">
                            View Orders
                        </button>
                        <button onClick={() => navigate('/admin/dashboard/products')} className="px-5 py-2.5 bg-gold-500 text-brand-900 rounded-xl hover:bg-gold-400 transition font-semibold text-sm">
                            Manage Products
                        </button>
                    </div>
                </div>
            </motion.div>

            {/* Stats Grid */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                {statCards.map((card, index) => (
                    <StatCard key={card.label} {...card} loading={isLoading} />
                ))}
            </div>

            {/* Recent Orders & Status */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Recent Orders */}
                <SectionCard
                    title="Recent Orders"
                    subtitle="Latest order activity"
                    className="lg:col-span-2"
                    actions={
                        <button onClick={() => navigate('/admin/dashboard/orders')} className="text-sm text-brand-600 hover:text-brand-700 dark:text-gold-400 font-medium flex items-center gap-1">
                            View All <ArrowRightIcon className="w-4 h-4" />
                        </button>
                    }
                >
                    {isLoading ? (
                        <div className="space-y-3">
                            {[...Array(5)].map((_, i) => (
                                <div key={i} className="animate-pulse flex items-center gap-4 py-3">
                                    <div className="h-10 w-10 bg-slate-200 dark:bg-brand-700 rounded-lg" />
                                    <div className="flex-1 space-y-2">
                                        <div className="h-4 w-32 bg-slate-200 dark:bg-brand-700 rounded" />
                                        <div className="h-3 w-20 bg-slate-200 dark:bg-brand-700 rounded" />
                                    </div>
                                    <div className="h-6 w-16 bg-slate-200 dark:bg-brand-700 rounded-full" />
                                </div>
                            ))}
                        </div>
                    ) : recentOrders.length === 0 ? (
                        <div className="text-center py-8">
                            <ShoppingCart className="w-12 h-12 text-slate-300 mx-auto mb-3" />
                            <p className="text-slate-500">No orders yet</p>
                        </div>
                    ) : (
                        <div className="divide-y divide-slate-100 dark:divide-brand-700">
                            {recentOrders.slice(0, 8).map((order) => (
                                <div key={order.id} className="flex items-center justify-between py-3 hover:bg-slate-50 dark:hover:bg-brand-800/30 px-2 -mx-2 rounded-lg transition-colors cursor-pointer">
                                    <div className="flex items-center gap-3">
                                        <div className="h-10 w-10 rounded-lg bg-slate-100 dark:bg-brand-800 flex items-center justify-center">
                                            <Package className="w-5 h-5 text-slate-400" />
                                        </div>
                                        <div>
                                            <p className="text-sm font-semibold text-brand-800 dark:text-white">{order.productName}</p>
                                            <p className="text-xs text-slate-500">{order.customerName}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3">
                                        <span className="text-sm font-bold text-brand-800 dark:text-white">${order.totalAmount?.toFixed(2)}</span>
                                        <StatusBadge status={order.status} size="sm" />
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </SectionCard>

                {/* Order Status Overview */}
                <SectionCard title="Order Status" subtitle="Distribution">
                    {isLoading ? (
                        <div className="space-y-3">
                            {[...Array(5)].map((_, i) => (
                                <div key={i} className="animate-pulse flex items-center gap-3">
                                    <div className="h-3 w-3 bg-slate-200 dark:bg-brand-700 rounded-full" />
                                    <div className="flex-1 h-4 bg-slate-200 dark:bg-brand-700 rounded" />
                                    <div className="h-4 w-8 bg-slate-200 dark:bg-brand-700 rounded" />
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="space-y-3">
                            {ordersByStatus.map((item) => (
                                <div key={item.status} className="flex items-center justify-between">
                                    <div className="flex items-center gap-2">
                                        <StatusBadge status={item.status} size="sm" />
                                    </div>
                                    <span className="text-sm font-bold text-brand-800 dark:text-white">{item.count}</span>
                                </div>
                            ))}
                            {ordersByStatus.length === 0 && (
                                <p className="text-slate-500 text-sm text-center py-4">No data available</p>
                            )}
                        </div>
                    )}
                </SectionCard>
            </div>
        </div>
    );
};

export default AdminOverview;
